RESULTS = []
def check(name: str, ok: bool, detail: str = ""):
    RESULTS.append((name, bool(ok), detail))
    print(f"[{'PASS' if ok else 'FAIL'}] {name}" + (f" | {detail}" if detail else ""))
def _lan_ok(lag, st) -> bool:
    """lag 0 must read as current, lag > 0 must read as stale and say so."""
    if lag == 0:
        return st.get("stale") is False and "NOT current" not in str(st.get("reason"))
    return st.get("stale") is True and "NOT current" in str(st.get("reason"))
def _bar_lag_td(face_day, panel_day):
    """Trading days from face_day (exclusive) to panel_day (inclusive), off the local calendar.

    E410: a face written only from a session script has no chain leg to re-derive it, so the
    only honest freshness reader is a bound on how many bars it may sit behind the panel.
    Returns 0 when the dates match and None when either date is unusable or the face is AHEAD
    of the panel -- a caller that guessed a number there would price an age it never measured.
    """
    try:
        import pandas as _pd
        a, b = _pd.Timestamp(face_day), _pd.Timestamp(panel_day)
        if a == b:
            return 0
        if a > b:
            return None
        _cal = _pd.to_datetime(_pd.read_csv("data/exchange_calendar.csv")["date"])
        return int(((_cal > a) & (_cal <= b)).sum())
    except Exception:
        return None
CENSUS_DRIFT = []


def _census_corpus_moved(face, fresh):
    """Did the two builds census the same corpus?

    An equality between a published census and a rebuild is a reproduction test only if
    both counted the same corpus.  A date cutoff cannot pin that -- the corpus is a live
    directory other lanes write all day, so 7 faces here carry today's cutoff and a
    different population.  The population size can say which of the two happened, and
    "the corpus moved" is a fact about the corpus, not a defect in the face.
    """
    def size(d):
        c = (d or {}).get("corpus") or {}
        for k in ("files", "sources", "faces"):
            if isinstance(c.get(k), int):
                return c[k]
        s = (d or {}).get("summary") or {}
        for k in ("faces_scanned", "sources_scanned", "corpus_files", "n_leaf_witnesses",
                  "source_family_pairs", "legs_in_smoke_test", "sites", "faces"):
            if isinstance(s.get(k), int):
                return s[k]
        return None
    a, b = size(face), size(fresh)
    return (a is not None and b is not None and a != b), a, b


def _census_shrank(bad, then, now):
    """A corpus that grew is a fact about the corpus; one that lost files is not."""
    if isinstance(then, int) and isinstance(now, int) and now < then:
        bad.append("the corpus shrank since publication (%s -> %s), so the published "
                   "population cannot be explained by growth" % (then, now))
    return bad


def _census_rebuild_scratch(mod, **kw):
    """Rebuild a census face into a scratch directory.

    e328/e329/e332 resolve `outdir or OUTDIR` and write, so a plain build() inside a leg
    republishes the very face the leg is about to compare -- the checker becomes the
    writer and the numbers are compared against its own output (r1261 family).  A checker
    must not mutate its subject, so the rebuild lands beside the corpus, not in it.
    """
    import shutil
    import tempfile
    out = tempfile.mkdtemp(prefix="smoke_census_")
    try:
        return mod.build(outdir=out, **kw)
    finally:
        shutil.rmtree(out, ignore_errors=True)


def _named_pin_corpus(face):
    """The corpus a face was built over, rebuilt from the pin the face itself names.

    E363: a census face quotes a population size.  Comparing that size against today's disk makes
    the leg's verdict a function of what other lanes happened to write, and comparing it against
    "the newest pin" does not work either -- a pin is taken after the face, so it describes a later
    corpus (measured: published 2362 / live 2367 / newest pin 2365 / publishing commit 2227).
    The only address that reproduces a face is the one the face wrote down, so the leg replays that
    pin and refuses a face that names none.
    """
    source = (face or {}).get("corpus_source") or {}
    pin_file = source.get("pin_file")
    if not pin_file:
        raise RuntimeError("the face names no corpus (E363 corpus_source)")
    path = os.path.join("results", "state_tilt", pin_file)
    if not os.path.exists(path):
        raise RuntimeError("the named corpus pin %s is not on disk" % (pin_file,))
    sys.path.insert(0, os.path.join(os.getcwd(), "scripts"))
    import e362_corpus_replay as _e362
    import e363_corpus_vintage as _e363
    import e361_census_corpus_pin as _e361
    pin = _e361.load_pin(path)
    gits = [s for s in pin["sources"] if s.get("tracked") and not s.get("dirty")]
    from_git, _missing = _e362.blob_texts(pin["git_commit"], [s["path"] for s in gits])
    store = _e362.load_store(pin["pin_id"])
    texts = dict(from_git)
    for p, blob in store["texts"].items():
        texts.setdefault(p, _e362.decode_text(blob))
    return texts, pin_file


