            if not _pol90.get("n_widening_demands") or not _pol90.get("n_narrowing_demands"):
                _bad90.append("a demand set is empty: the polarity claim cannot be checked")
            sys.path.insert(0, os.path.join(os.getcwd(), "scripts"))
