                str(((_f372 or {}).get("studies", {}).get("E350", {})
                     .get("pin_only", {}).get("numbers", {}).get("corpus_sources"))),
                str(((_f372 or {}).get("studies", {}).get("E350", {})
                     .get("pin_plus_store", {}).get("numbers", {}).get("corpus_sources"))),
